{"command":"python3 << 'EOF'
import csv

# Verify both files parse correctly with csv.reader (RFC 4180 compliant)
for fname in ['outputs/t12_missingness_report.csv', 'outputs/t12_selected_matrix.csv']:
    with open(fname, 'r', newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = next(reader)
        expected_cols = len(header)
        for i, row in enumerate(reader, 1):
            if len(row) != expected_cols:
                print(f"ERROR in {fname} row {i}: expected {expected_cols} cols, got {len(row)}")
                print(f"  Row: {row}")
                break
        else:
            print(f"{fname}: OK - {i} data rows, {expected_cols} columns each")
EOF"}
